local UIFightTeamTitleInfoNode = Class("UIFightTeamTitleInfoNode")


function UIFightTeamTitleInfoNode:__init() 
    self._levelId = 0
    self._curLevelVo = nil
    self._extraData = nil
    self._curLevelType = nil
end

function UIFightTeamTitleInfoNode:__delete()
    self._levelId = nil
    self._curLevelVo = nil
    self._extraData = nil
    self._curLevelType = nil
end

function UIFightTeamTitleInfoNode:Awake()
end

function UIFightTeamTitleInfoNode:Start()
end

function UIFightTeamTitleInfoNode:Refresh(levelId, extraData)
    self._levelId      = checkInt(levelId)
    self._curLevelVo   = QuestConfMgr:GetInstance():GetQuestVoById(self._levelId)
    self._curLevelType = GoodsUtils.GetIdType(self._levelId, Constants.IDArea.Quests)     --关卡类型
    self._extraData    = extraData
    if not self._curLevelVo then
        return
    end

    KTool.SetActive(self.Patrol, self._curLevelType == Constants.IDType.QuestMaze)
    KTool.SetActive(self.OneGroup, self._curLevelType ~= Constants.IDType.QuestMaze)
    if self._curLevelType == Constants.IDType.QuestMaze then 
        self:FillMazeTitle()
    else
        self:FillCommonTitle()
    end
end

--通用的
function UIFightTeamTitleInfoNode:FillCommonTitle()
    --CfUtils.FillText(self.BattleName, QuestConfMgr:GetInstance():GetTitleName(self._curLevelType))
    local levelName  = self._curLevelVo.name
    local battleName = self._curLevelVo.name

    if self._curLevelType == Constants.IDType.QuestTalent then 
        levelName = self._curLevelVo.name
        battleName = self._curLevelVo.label

    elseif self._curLevelType == Constants.IDType.QuestMain then
        levelName = string.format("%s %s", self._curLevelVo.label, self._curLevelVo.name)

    elseif self._curLevelType == Constants.IDType.QuestPatrolMaze then 
        ---@type PatrolMazeAreaDojo @ 当前所在区域dojo
        local areaDojo = self._extraData.areaDojo
        ---@type PatrolMazeFloorPathDojo @ 路径节点dojo
        local pathDojo = self._extraData.pathDojo
        ---@type PatrolMazeFloorLevelDojo @ 层级节点dojo
        local levelDojo = self._extraData.levelDojo
        local PatrolMazeUtils = import('Game.UI.PatrolMaze.PatrolMazeUtils')
        local questTypeVo = PatrolMazeUtils.GetQuestTypeVo(levelDojo.questType)
        levelName = questTypeVo.typeName
    elseif self._curLevelType == Constants.IDType.Fairyland then
        ---@type FairylandLevelVo
        local fairylandLevelVo = CfUtils.GetCfVo(AutoIds.IdSetting6162, "FairylandLevelVo", self._levelId)
        if fairylandLevelVo then
            levelName = fairylandLevelVo.name
        else
            local ConstantsFairyland = import("Game.Fairyland.ConstantsFairyland")
            levelName = ConstantsFairyland.MirrorLevelName
        end
    end
    
    if not string.isEmpty(levelName) then
        levelName = string.gsub(levelName, "\\n", "")
    end
    
    CfUtils.FillText(self.LevelName, levelName)
    CfUtils.FillText(self.BattleName, battleName)
end

